B['valid-anagram']=r'''std::istringstream in(q.data);std::string a,b;std::getline(in,a);std::getline(in,b);std::sort(a.begin(),a.end());std::sort(b.begin(),b.end());return scalar(a==b);'''
B['two-sum']=r'''auto a=q.vector();I target=q.one();std::unordered_map<I,I> seen;for(I i=0;i<(I)a.size();++i){auto it=seen.find(target-a[i]);if(it!=seen.end())return row({it->second,i});seen[a[i]]=i;}throw std::runtime_error("pair");'''
B['group-anagrams']=r'''I n=q.one();std::istringstream in(q.data.substr(q.cursor+1));std::map<std::string,std::vector<std::string>> groups;std::string word,out;for(I i=0;i<n;++i){std::getline(in,word);auto key=word;std::sort(key.begin(),key.end());groups[key].push_back(word);}for(auto&[key,words]:groups){std::sort(words.begin(),words.end());for(std::size_t i=0;i<words.size();++i){if(i)out+=' ';out+=words[i];}out+='\n';}return out;'''
B['top-k-frequent-elements']=r'''auto a=q.vector();I k=q.one();std::unordered_map<I,I> counts;for(I x:a)++counts[x];std::vector<std::pair<I,I>> ranked;for(auto[x,n]:counts)ranked.emplace_back(-n,x);std::sort(ranked.begin(),ranked.end());V out;for(I i=0;i<k;++i)out.push_back(ranked[i].second);return row(out);'''
B['product-of-array-except-self']=r'''auto a=q.vector();V out(a.size());I product=1;for(std::size_t i=0;i<a.size();++i){out[i]=product;product*=a[i];}product=1;for(I i=(I)a.size()-1;i>=0;--i){out[i]*=product;product*=a[i];}return row(out);'''
B['encode-and-decode-strings']=r'''I count=q.one();std::size_t pos=q.data.find('\n')+1;std::string out;for(I i=0;i<count;++i){auto end=q.data.find('\n',pos);I n=std::stoll(q.data.substr(pos,end-pos));pos=end+1;out+=std::to_string(n)+":"+q.data.substr(pos,n);pos+=n;}return out;'''
B['longest-consecutive-sequence']=r'''auto a=q.vector();std::unordered_set<I> values(a.begin(),a.end());I best=0;for(I x:values)if(!values.count(x-1)){I end=x;while(values.count(end))++end;best=std::max(best,end-x);}return scalar(best);'''
B['two-sum-ii-input-array-is-sorted']=r'''auto a=q.vector();I t=q.one(),l=0,r=a.size()-1;while(l<r){I s=a[l]+a[r];if(s==t)return row({l,r});if(s<t)++l;else --r;}throw std::runtime_error("pair");'''
B['container-with-most-water']=r'''auto a=q.vector();I l=0,r=(I)a.size()-1,best=0;while(l<r){best=std::max(best,(r-l)*std::min(a[l],a[r]));if(a[l]<a[r])++l;else --r;}return scalar(best);'''
B['trapping-rain-water']=r'''auto a=q.vector();I l=0,r=(I)a.size()-1,left=0,right=0,total=0;while(l<=r){if(left<=right){left=std::max(left,a[l]);total+=left-a[l++];}else{right=std::max(right,a[r]);total+=right-a[r--];}}return scalar(total);'''
