B['permutation-in-string']=r'''std::istringstream in(q.data);std::string a,b;std::getline(in,a);std::getline(in,b);std::array<I,256> count{},window{};for(unsigned char x:a)++count[x];if(a.empty())return scalar(1);for(std::size_t i=0;i<b.size();++i){++window[(unsigned char)b[i]];if(i>=a.size())--window[(unsigned char)b[i-a.size()]];if(window==count)return scalar(1);}return scalar(0);'''
B['minimum-window-substring']=r'''std::istringstream in(q.data);std::string text,pattern;std::getline(in,text);std::getline(in,pattern);if(pattern.empty())return "\n";std::array<I,256> need{};for(unsigned char x:pattern)++need[x];I missing=pattern.size(),left=0,start=0,size=INT64_MAX;for(I r=0;r<(I)text.size();++r){auto x=(unsigned char)text[r];if(need[x]>0)--missing;--need[x];while(!missing){if(r-left+1<size){start=left;size=r-left+1;}auto old=(unsigned char)text[left++];if(++need[old]>0)++missing;}}return (size==INT64_MAX?"":text.substr(start,size))+"\n";'''
B['sliding-window-maximum']=r'''auto a=q.vector();I k=q.one();std::deque<I> queue;V out;for(I i=0;i<(I)a.size();++i){while(!queue.empty()&&queue.front()<=i-k)queue.pop_front();while(!queue.empty()&&a[queue.back()]<=a[i])queue.pop_back();queue.push_back(i);if(i>=k-1)out.push_back(a[queue.front()]);}return row(out);'''
