B['min-cost-to-connect-all-points']=r'''auto a=q.matrix(2);I n=a.size(),total=0;V dist(n,INT64_MAX);std::vector<bool>seen(n);if(n)dist[0]=0;for(I k=0;k<n;++k){I u=-1;for(I i=0;i<n;++i)if(!seen[i]&&(u==-1||dist[i]<dist[u]))u=i;total+=dist[u];seen[u]=true;for(I v=0;v<n;++v)if(!seen[v])dist[v]=std::min(dist[v],std::abs(a[u][0]-a[v][0])+std::abs(a[u][1]-a[v][1]));}return scalar(total);'''
B['swim-in-rising-water']=r'''I r=q.one(),c=r;V a(r*r);for(auto&x:a)x=q.one();auto neighbours=[&](I u){V v;if(u/c)v.push_back(u-c);if(u/c+1<r)v.push_back(u+c);if(u%c)v.push_back(u-1);if(u%c+1<c)v.push_back(u+1);return v;};V dist(a.size(),INT64_MAX);dist[0]=a[0];using P=std::pair<I,I>;std::priority_queue<P,std::vector<P>,std::greater<P>>heap;heap.emplace(a[0],0);while(!heap.empty()){auto[d,u]=heap.top();heap.pop();if(u==(I)a.size()-1)return scalar(d);if(d!=dist[u])continue;for(I v:neighbours(u)){I next=std::max(d,a[v]);if(next<dist[v]){dist[v]=next;heap.emplace(next,v);}}}throw std::runtime_error("path");'''
B['alien-dictionary']=r'''std::istringstream in(q.data);I n;in>>n;std::vector<std::string>words(n);std::map<char,std::set<char>>adj;std::map<char,I>degree;for(auto&w:words){in>>w;for(char x:w){adj[x];degree[x];}}for(I i=1;i<n;++i){auto&a=words[i-1];auto&b=words[i];std::size_t j=0;while(j<std::min(a.size(),b.size())&&a[j]==b[j])++j;if(j==std::min(a.size(),b.size())){if(a.size()>b.size())return "-1\n";}else if(adj[a[j]].insert(b[j]).second)++degree[b[j]];}std::priority_queue<char,std::vector<char>,std::greater<char>>heap;for(auto[x,d]:degree)if(!d)heap.push(x);std::string out;while(!heap.empty()){char u=heap.top();heap.pop();out+=u;for(char v:adj[u])if(--degree[v]==0)heap.push(v);}return (out.size()==adj.size()?out:"-1")+'\n';'''
B['design-add-and-search-words-data-structure']=r'''std::istringstream in(q.data);I n;in>>n;std::string line,out;std::getline(in,line);std::vector<std::map<char,I>>trie(1);std::vector<bool>end(1);for(I i=0;i<n;++i){std::getline(in,line);char op=line[0];auto word=line.substr(2);if(op=='+'){I u=0;for(char x:word){auto it=trie[u].find(x);if(it==trie[u].end()){I next=trie.size();trie[u][x]=next;trie.emplace_back();end.push_back(false);u=next;}else u=it->second;}end[u]=true;}else{V frontier{0};for(char x:word){V next;for(I u:frontier)for(auto[c,v]:trie[u])if(x=='.'||x==c)next.push_back(v);frontier=next;}bool found=false;for(I u:frontier)found|=end[u];out+=scalar(found);}}return out;'''
B['design-twitter']=r'''std::istringstream in(q.data);I n,clock=0;in>>n;std::map<I,std::set<I>>follow;std::map<I,std::vector<std::pair<I,I>>>posts;std::string out;for(I i=0;i<n;++i){std::string op;I u,v;in>>op>>u;if(op=="post"){in>>v;posts[u].emplace_back(clock++,v);}else if(op=="follow"){in>>v;follow[u].insert(v);}else if(op=="unfollow"){in>>v;follow[u].erase(v);}else{auto who=follow[u];who.insert(u);using T=std::array<I,3>;std::priority_queue<T>heap;for(I w:who)if(!posts[w].empty())heap.push({posts[w].back().first,w,I(posts[w].size()-1)});V feed;while(!heap.empty()&&feed.size()<10){auto[t,w,j]=heap.top();heap.pop();feed.push_back(posts[w][j].second);if(j)heap.push({posts[w][j-1].first,w,j-1});}out+=row(feed);}}return out;'''
