B['regular-expression-matching']=r'''std::istringstream in(q.data);std::string text,p;std::getline(in,text);std::getline(in,p);std::vector<bool>dp(p.size()+1);dp[0]=true;for(std::size_t j=2;j<=p.size();++j)if(p[j-1]=='*')dp[j]=dp[j-2];for(char x:text){auto prev=dp;std::fill(dp.begin(),dp.end(),false);for(std::size_t j=1;j<=p.size();++j){if(p[j-1]=='*')dp[j]=dp[j-2]||(prev[j]&&(p[j-2]=='.'||p[j-2]==x));else dp[j]=prev[j-1]&&(p[j-1]=='.'||p[j-1]==x);}}return scalar(dp.back());'''
