B['minimum-interval-to-include-each-query']=r'''auto a=q.matrix(2);auto queries=q.vector();std::sort(a.begin(),a.end());std::vector<std::pair<I,I>>sorted;for(I i=0;i<(I)queries.size();++i)sorted.emplace_back(queries[i],i);std::sort(sorted.begin(),sorted.end());using P=std::pair<I,I>;std::priority_queue<P,std::vector<P>,std::greater<P>>heap;V out(queries.size(),-1);I i=0;for(auto[x,j]:sorted){while(i<(I)a.size()&&a[i][0]<=x){heap.emplace(a[i][1]-a[i][0]+1,a[i][1]);++i;}while(!heap.empty()&&heap.top().second<x)heap.pop();if(!heap.empty())out[j]=heap.top().first;}return row(out);'''
