# Export only includes and support methods used by each original kernel.
BASE_INCLUDES=['charconv','cstdint','fstream','iostream','stdexcept','string','vector']
EXTRA_INCLUDES={'std::sort':'algorithm','std::max':'algorithm','std::min':'algorithm','std::reverse':'algorithm','std::merge':'algorithm','std::lower_bound':'algorithm','std::binary_search':'algorithm','std::next_permutation':'algorithm','std::fill':'algorithm','std::count':'algorithm','std::array':'array','std::function':'functional','std::map':'map','std::set':'set','std::unordered_map':'unordered_map','std::unordered_set':'unordered_set','std::priority_queue':'queue','std::queue':'queue','std::deque':'deque','std::list':'list','std::istringstream':'sstream','std::ostringstream':'sstream','std::setprecision':'iomanip','std::back_inserter':'iterator','std::prev':'iterator'}
def source(slug):
    body=B[slug];header=HEADER[HEADER.index('using I'):]
    includes=set(BASE_INCLUDES)|{inc for token,inc in EXTRA_INCLUDES.items() if token in body}
    if 'q.matrix(' not in body:header=header[:header.index(' std::vector<V> matrix')]+header[header.index('};\nstd::string scalar'):]
    if 'q.vector(' not in body:header=header[:header.index(' V vector()')]+header[header.index(' std::vector<V> matrix'):] if 'q.matrix(' in body else header[:header.index(' V vector()')]+header[header.index('};\nstd::string scalar'):]
    need_rows='rows(' in body;need_row='row(' in body or need_rows;need_scalar='scalar(' in body
    if not need_rows:header=header[:header.index('std::string rows(')]
    if not need_row:
        start=header.index('std::string row(');end=header.index('std::string rows(') if need_rows else len(header);header=header[:start]+header[end:]
    if not need_scalar:
        start=header.index('std::string scalar(');end=header.index('std::string row(') if need_row else len(header);header=header[:start]+header[end:]
    return ''.join('#include <'+i+'>\n' for i in sorted(includes))+header+'std::string solve(Input &q){'+body+'}\n'+DRIVER
